```python
def hex_to_int(hex_str: str) -> int:
    """
    Convert a hexadecimal string to an integer.

    Accepts an optional leading '+' or '-' sign and an optional '0x'/'0X' prefix.
    Raises ValueError if the string is empty or contains any non-hex characters.
    """
    if not isinstance(hex_str, str):
        raise TypeError("Input must be a string")

    s = hex_str.strip()
    if not s:
        raise ValueError("Empty string is not a valid hex number")

    sign = 1
    if s[0] in "+-":
        if s[0] == "-":
            sign = -1
        s = s[1:]

    if s[:2].lower() == "0x":
        s = s[2:]

    if not s:
        raise ValueError(f"Invalid hex string: {hex_str!r}")

    # Validate every character is a hex digit.
    valid_digits = set("0123456789abcdefABCDEF")
    for ch in s:
        if ch not in valid_digits:
            raise ValueError(f"Invalid hex character {ch!r} in {hex_str!r}")

    return sign * int(s, 16)


if __name__ == "__main__":
    # Valid cases
    assert hex_to_int("ff") == 255
    assert hex_to_int("0xFF") == 255
    assert hex_to_int("-0x1A") == -26
    assert hex_to_int("+10") == 16
    assert hex_to_int("DEADBEEF") == 0xDEADBEEF

    # Invalid cases
    for bad in ["", "0x", "xyz", "12g4", "0x1G", "  ", "1.5", "0b101"]:
        try:
            hex_to_int(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"Expected ValueError for {bad!r}")

    print("All tests passed.")
```

Key points:

- **Validation first**: every character after stripping the sign and `0x` prefix is checked against the set of hex digits, so inputs like `"12g4"` or `"0x1G"` raise `ValueError` instead of being silently accepted.
- **Sign and prefix handling**: supports `+`/`-` and optional `0x`/`0X`, matching common conventions.
- **No reliance on `int(s, 16)` alone** for validation, since `int` would accept things like underscores (`"1_0"`) or surrounding whitespace in some cases; the explicit check keeps the contract strict.

```python
from pathlib import Path


def fibonacci(n: int) -> int:
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 2:
        return n
    previous, current = 0, 1
    for _ in range(n - 1):
        previous, current = current, previous + current
    return current


def fibonacci_from_file(path: Path, n: int) -> int:
    if not path.exists():
        raise ValueError(f"file not found: {path}")
    return fibonacci(n)
```

