```python
from pathlib import Path

def decimal_to_binary(decimal_number: int) -> str:
    if not isinstance(decimal_number, int):
        raise ValueError("Input must be an integer")
    if decimal_number < 0:
        raise ValueError("Input must be non-negative")
    if decimal_number == 0:
        return "0"
    digits: list[str] = []
    remaining: int = decimal_number
    while remaining > 0:
        digits.append(f"{remaining % 2}")
        remaining //= 2
    return "".join(reversed(digits))
```

```python
from pathlib import Path

def find_newest_file(directory: str) -> Path:
    path = Path(directory)
    if not path.is_dir():
        raise ValueError(f"Not a directory: {directory}")
    files = [p for p in path.iterdir() if p.is_file()]
    if not files:
        raise ValueError(f"No files found in: {directory}")
    return max(files, key=lambda p: p.stat().st_mtime)
```

```python
from pathlib import Path

def join_path(base_directory: str, filename: str) -> Path:
    if not base_directory:
        raise ValueError("base_directory must not be empty")
    if not filename:
        raise ValueError("filename must not be empty")
    base_path = Path(base_directory)
    if not base_path.is_absolute():
        raise ValueError(f"base_directory must be absolute: {base_directory}")
    if Path(filename).is_absolute():
        raise ValueError(f"filename must be relative: {filename}")
    return base_path / filename
```

