from typing import Any

def flatten_nested_list(nested_list: list[Any]) -> list[int]:
    if not isinstance(nested_list, list):
        raise ValueError("Input must be a list")
    result: list[int] = []
    for item in nested_list:
        if isinstance(item, list):
            result.extend(flatten_nested_list(item))
            continue
        if not isinstance(item, int) or isinstance(item, bool):
            raise ValueError(f"Invalid element: {item!r}")
        result.append(item)
    return result
```

```python
from typing import List


def longest_common_prefix(strs: List[str]) -> str:
    """Return the longest common prefix of a list of strings.

    Returns an empty string if the list is empty or no common prefix exists.
    Raises TypeError if any element is not a string.
    """
    if not isinstance(strs, list):
        raise TypeError(f"Expected a list of strings, got {type(strs).__name__}")

    if not strs:
        return ""

    for i, s in enumerate(strs):
        if not isinstance(s, str):
            raise TypeError(
                f"Element at index {i} is {type(s).__name__}, expected str"
            )

    # The common prefix cannot be longer than the shortest string.
    shortest = min(strs, key=len)

    for i, ch in enumerate(shortest):
        for s in strs:
            if s[i] != ch:
                return shortest[:i]

    return shortest
```

```python
from typing import Any, List


def flatten(nested: List[Any]) -> List[int]:
    """Recursively flatten a nested list of integers into a flat list.

    Raises:
        TypeError: If any non-list, non-int element is encountered.
    """
    result: List[int] = []

    def _walk(item: Any, path: str) -> None:
        if isinstance(item, list):
            for index, child in enumerate(item):
                _walk(child, f"{path}[{index}]")
        elif isinstance(item, int) and not isinstance(item, bool):
            result.append(item)
        else:
            raise TypeError(
                f"Unsupported element at {path}: {item!r} "
                f"(type {type(item).__name__}); expected int or list"
            )

    if not isinstance(nested, list):
        raise TypeError(
            f"Expected a list, got {type(nested).__name__}"
        )

    _walk(nested, "input")
    return result
```

```python
def compound_interest(principal: float, rate: float, periods: int, compounds_per_period: int = 1) -> float:
    """
    Compute compound interest.

    Formula: A = P * (1 + r/n)^(n*t)
      P = principal
      r = annual interest rate (as a decimal, e.g. 0.05 for 5%)
      n = compounding frequency per period
      t = number of periods

    Raises:
        ValueError: if principal is negative, or other inputs are invalid.
        TypeError: if inputs are not numeric.
    """
    # Validate types
    if not isinstance(principal, (int, float)) or isinstance(principal, bool):
        raise TypeError(f"principal must be a number, got {type(principal).__name__}")
    if not isinstance(rate, (int, float)) or isinstance(rate, bool):
        raise TypeError(f"rate must be a number, got {type(rate).__name__}")
    if not isinstance(periods, (int, float)) or isinstance(periods, bool):
        raise TypeError(f"periods must be a number, got {type(periods).__name__}")
    if not isinstance(compounds_per_period, int) or isinstance(compounds_per_period, bool):
        raise TypeError(
            f"compounds_per_period must be an int, got {type(compounds_per_period).__name__}"
        )

    # Validate values
    if principal < 0:
        raise ValueError(f"principal must be non-negative, got {principal}")
    if compounds_per_period <= 0:
        raise ValueError(
            f"compounds_per_period must be positive, got {compounds_per_period}"
        )
    if periods < 0:
        raise ValueError(f"periods must be non-negative, got {periods}")

    # Base case: zero principal yields zero regardless of rate
    if principal == 0:
        return 0.0

    # Guard against a base <= 0 raised to a fractional power (undefined in reals)
    base = 1 + rate / compounds_per_period
    if base < 0:
        raise ValueError(
            f"invalid rate {rate} for {compounds_per_period} compounding(s) per period: "
            f"base (1 + rate/n) = {base} is negative"
        )

    exponent = compounds_per_period * periods
    try:
        return principal * (base ** exponent)
    except OverflowError as exc:
        raise OverflowError(
            f"compound interest overflow for principal={principal}, rate={rate}, "
            f"periods={periods}, compounds_per_period={compounds_per_period}"
        ) from exc
```

