```python
from typing import Any

def intersection_without_duplicates(first: list[Any], second: list[Any]) -> list[Any]:
    if not isinstance(first, list) or not isinstance(second, list):
        raise ValueError("Both arguments must be lists")
    seen: set[Any] = set()
    result: list[Any] = []
    for item in first:
        if item in second and item not in seen:
            seen.add(item)
            result.append(item)
    return result
```

```python
def transpose_matrix(matrix: list[list[int]]) -> list[list[int]]:
    if not matrix or not all(isinstance(row, list) for row in matrix):
        raise ValueError("matrix must be a non-empty list of lists")
    if any(len(row) != len(matrix[0]) for row in matrix):
        raise ValueError("all rows must have the same length")
    return [[matrix[r][c] for r in range(len(matrix))] for c in range(len(matrix[0]))]
```

```python
def is_palindrome(text: str) -> bool:
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    cleaned = "".join(char.lower() for char in text if char != " ")
    if not cleaned:
        return True
    return cleaned == cleaned[::-1]
```

