from typing import Final

ROMAN_VALUES: Final[dict[str, int]] = {
    "I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000,
}

def roman_to_int(roman: str) -> int:
    if not roman or any(char not in ROMAN_VALUES for char in roman):
        raise ValueError(f"Invalid Roman numeral: {roman}")
    total: int = 0
    for index, char in enumerate(roman):
        value: int = ROMAN_VALUES[char]
        next_value: int = ROMAN_VALUES[roman[index + 1]] if index + 1 < len(roman) else 0
        total += -value if value < next_value else value
    return total
```

```python
from typing import List, Optional, Tuple

def find_two_sum(numbers: List[int], target: int) -> Optional[Tuple[int, int]]:
    if not isinstance(numbers, list) or not isinstance(target, int):
        raise ValueError("numbers must be a list and target must be an int")
    seen: dict[int, int] = {}
    for index, value in enumerate(numbers):
        if not isinstance(value, int):
            raise ValueError("all elements must be ints")
        complement = target - value
        if complement in seen:
            return (seen[complement], index)
        seen[value] = index
    return None
```

```python
from typing import List

def median(numbers: List[float]) -> float:
    if not numbers:
        raise ValueError("numbers must not be empty")
    ordered = sorted(numbers)
    middle = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return float(ordered[middle])
    return (ordered[middle - 1] + ordered[middle]) / 2.0
```

```python
from typing import Final

OPENING: Final[dict[str, str]] = {"(": ")", "[": "]", "{": "}"}
CLOSING: Final[set[str]] = {")", "]", "}"}

def are_brackets_balanced(text: str) -> bool:
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    stack: list[str] = []
    for char in text:
        if char in OPENING:
            stack.append(OPENING[char])
        elif char in CLOSING:
            if not stack or stack.pop() != char:
                return False
    return not stack
```

