from typing import Union

def percentage_to_float(value: Union[str, float, int]) -> float:
    if not isinstance(value, str):
        raise ValueError(f"expected str, got {type(value).__name__}")
    text = value.strip()
    if not text.endswith("%"):
        raise ValueError(f"missing percent sign: {value!r}")
    number = text[:-1].strip()
    if not number:
        raise ValueError(f"empty numeric part: {value!r}")
    try:
        result = float(number)
    except ValueError:
        raise ValueError(f"invalid number: {number!r}")
    return result
```

