from pathlib import Path

def is_balanced(text: str) -> bool:
    pairs = {")": "(", "]": "[", "}": "{"}
    stack: list[str] = []
    for char in text:
        if char in "([{":
            stack.append(char)
            continue
        if char not in pairs:
            continue
        if not stack or stack.pop() != pairs[char]:
            return False
    return not stack

def is_balanced_file(path: Path) -> bool:
    if not path.is_file():
        raise ValueError(f"Not a file: {path}")
    return is_balanced(path.read_text())
```

